<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>工作室类</title>
<style>
  body {
    margin: 0;
    padding: 20px;
    background-color: #1a1a1a;
    display: flex;
    justify-content: center;
    font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
  }
  .poster {
    width: 700px;
    background-color: #3a3635;
    border-radius: 20px;
    padding: 40px;
    box-sizing: border-box;
    color: #ffffff;
    position: relative;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  }
  .watermark {
    position: absolute;
    bottom: -20px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 180px;
    font-weight: bold;
    color: rgba(255, 255, 255, 0.04);
    z-index: 0;
    white-space: nowrap;
    pointer-events: none;
    font-family: sans-serif;
  }
  .content {
    position: relative;
    z-index: 1;
  }
  .header-container {
    text-align: center;
    margin-bottom: 30px;
  }
  .header-pill {
    display: inline-block;
    border: 1px solid #ffffff;
    border-radius: 30px;
    padding: 8px 25px;
    font-size: 14px;
    letter-spacing: 1px;
  }
  .header-pill strong {
    font-weight: bold;
    font-size: 16px;
  }
  .title {
    text-align: center;
    font-size: 48px;
    font-family: "SimSun", "STSong", serif;
    letter-spacing: 8px;
    margin: 0 0 40px 0;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  }
  .top-section {
    display: flex;
    gap: 25px;
    margin-bottom: 35px;
  }
  .image-placeholder {
    width: 320px;
    height: 220px;
    background-color: #e0e0e0;
    color: #333;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 5px;
    font-size: 14px;
    flex-shrink: 0;
  }
  .info-list {
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    flex-grow: 1;
  }
  .info-item {
    display: flex;
    align-items: flex-start;
    gap: 15px;
  }
  .pill-label {
    background: linear-gradient(90deg, #f5d0c5 0%, #ffffff 100%);
    color: #333333;
    padding: 6px 20px;
    border-radius: 20px;
    font-weight: bold;
    font-size: 16px;
    text-align: center;
    min-width: 60px;
    flex-shrink: 0;
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
  }
  .info-value {
    font-size: 14px;
    line-height: 1.6;
    padding-top: 4px;
  }
  .section {
    margin-bottom: 30px;
  }
  .section-title-container {
    margin-bottom: 20px;
  }
  .grid-4 {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px 10px;
  }
  .grid-2 {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px 10px;
  }
  .list-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 15px;
  }
  .icon {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
  }
  .reason-text {
    font-size: 14px;
    line-height: 1.8;
    color: #e0e0e0;
    text-align: justify;
  }
  .footer-container {
    text-align: center;
    margin-top: 50px;
  }
  .footer-pill {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    border: 1px solid #ffffff;
    border-radius: 30px;
    padding: 8px 25px;
    font-size: 14px;
  }
</style>
</head>
<body>

<div class="poster">
